def compute(vars):
    v_2006 = vars["v1"]
    v_2007 = vars["v2"]
    change = v_2007 - v_2006

    return {
        "value": change,
        "trace": {
            "v_2006": v_2006,
            "v_2007": v_2007,
            "change": change,
            "output_meta": {
                "currency": "USD",
                "scale": "million",
                "unit": "monetary"
            }
        }
    }
